def transform(grid):
    from collections import Counter, defaultdict
    out=[row[:] for row in grid]
    diag=defaultdict(Counter)
    for r in range(3,len(grid)):
        for c in range(3,len(grid[0])):
            if grid[r][c] != 0:
                diag[r+c][grid[r][c]] += 1
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v != 0: continue
            if r < 3 or c < 3:
                out[r][c] = 1 if r < 2 or c < 2 else 4
            else:
                counts=diag[r+c]
                out[r][c]=counts.most_common(1)[0][0]
    return out
